<script setup>
import LaunchUpdates from '@/Components/Marketplace/LaunchUpdates.vue';
import LaunchHome from '@/Components/Marketplace/LaunchHome.vue';
import { ref, nextTick } from 'vue';
import { useForm } from '@inertiajs/vue3';
import MarketplaceLayout from '@/Layouts/MarketplaceLayout.vue';
import MarketplaceMap from '@/Components/Locations/MarketplaceMap.vue';
import DiscoverySearch from '@/Components/Marketplace/DiscoverySearch.vue';
const resultView=ref('list');
import { Head, Link, router } from '@inertiajs/vue3';
import AppNotice from '@/Components/Product/AppNotice.vue';
import { ArrowRightIcon, MagnifyingGlassIcon, MapPinIcon, CalendarDaysIcon, ArrowUpRightIcon, SparklesIcon } from '@heroicons/vue/24/outline';
const props = defineProps({ filters: Object, results: Object, audiences: Array, bounded: Boolean, seo: Object, alternatives: Array, launchMode: Boolean, editorial: Object });
const query = ref(props.filters.q);
const location = ref(props.filters.location);
const busy = ref(false);
const rating = ref(props.filters.rating || '');
const sort = ref(props.filters.sort || 'name');
const appointmentDate=ref(props.filters.date || '');
const serviceCategory=ref(props.filters.category || '');
const nearbyError = ref('');
const nearbyBusy = ref(false);
const nearbyForm = useForm({latitude:null,longitude:null,q:'',category:'',date:'',rating:'',sort:'name'});
const showResults = () => nextTick(() => document.getElementById('salon-results')?.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}));
const searchPoint = point => {
    nearbyForm.latitude=point.lat;nearbyForm.longitude=point.lng;nearbyForm.q=query.value;nearbyForm.category=serviceCategory.value;
    nearbyForm.date=appointmentDate.value==='today' ? new Date().toLocaleDateString('en-CA') : appointmentDate.value;
    location.value='';nearbyForm.rating=rating.value;nearbyForm.sort=sort.value;
    nearbyForm.post('/marketplace/nearby',{preserveScroll:true,onSuccess:showResults,onFinish:()=>nearbyBusy.value=false});
};
const findNearby = () => {
    if (nearbyBusy.value) return;
    if (!navigator.geolocation) { nearbyError.value='Your browser cannot share a location. Enter a city or neighbourhood instead.'; return; }
    nearbyBusy.value=true;nearbyError.value='';
    navigator.geolocation.getCurrentPosition(position=>searchPoint({lat:position.coords.latitude,lng:position.coords.longitude}),()=>{nearbyBusy.value=false;nearbyError.value='We couldn’t use your location. Enter a city or neighbourhood to keep exploring.';},{maximumAge:0,timeout:10000,enableHighAccuracy:true});
};
const search = () => {
    if (busy.value) return;
    busy.value = true;
    router.get('/marketplace', { q: query.value, location: location.value, rating:rating.value, sort:sort.value, date:appointmentDate.value, category:serviceCategory.value, ...(props.filters.nearby && !location.value ? {nearby:1} : {}) }, {
        preserveState: true, preserveScroll: true, onSuccess: showResults, onFinish: () => { busy.value = false; },
    });
};
const resetSearch = () => { query.value='';location.value='';rating.value='';appointmentDate.value='';serviceCategory.value='';sort.value='name'; nearbyForm.delete('/marketplace/nearby',{preserveState:false}); };
const categories = props.audiences || [
    { name: 'Hair', query: 'hair', image: '/images/marketing/industries/home-salon-hero.webp', caption: 'A little reinvention.' },
    { name: 'Barber', query: 'barber', image: '/images/marketing/industries/barbershop.webp', caption: 'Keep it sharp.' },
    { name: 'Nails', query: 'nail', image: '/images/marketing/industries/nail-salon.webp', caption: 'The finishing touch.' },
];
function choose(term) { serviceCategory.value = term === 'nail' ? 'nails' : term; query.value = ''; search(); }
</script>

<template>
    <Head :title="seo?.title || 'Find your next appointment | Clipperdesk Marketplace'" />
    <MarketplaceLayout>
        <LaunchHome v-if="launchMode" :editorial="editorial" :audiences="audiences" :filters="filters" />
        <main v-else>
            <section class="market-hero">
                <div class="hero-copy"><p class="eyebrow"><span></span> GOOD PLACES. YOUR KIND OF PEOPLE.</p><h1>Your next<br />feel-good <em>find.</em></h1><p class="intro">An appointment that fits your day.<br />Explore local services and find your fit.</p><a href="#discover" class="explore-link">Discover your next favourite <ArrowRightIcon /></a></div>
                <div class="hero-art"><img src="/images/marketing/industries/home-salon-hero.webp" alt="A welcoming salon space" fetchpriority="high" /><div class="art-caption"><SparklesIcon /><span>A little time.<br />A good fit.</span></div><span class="image-note">A little inspiration for your next visit</span></div>
                <span class="hero-number" aria-hidden="true">01 / A MOMENT FOR YOU</span>
            </section>
            <section id="discover" class="discovery" tabindex="-1">
                <DiscoverySearch v-model:query="query" v-model:location="location" v-model:date="appointmentDate" :busy="busy" :nearby="filters.nearby" :nearby-busy="nearbyBusy || nearbyForm.processing" :salons="results.data" @search="search" @category="choose" @query-edit="serviceCategory=''" @service="name=>{query=name;serviceCategory='';search()}" @nearby="findNearby" @place="searchPoint" />
                <div v-if="filters.nearby" class="mp-actions"><span class="mp-muted">Within 25 km of your chosen location</span><button class="mp-button quiet" @click="nearbyForm.delete('/marketplace/nearby')">Clear nearby search</button></div>
                <AppNotice v-if="nearbyError" title="Try a city search" :description="nearbyError" style="margin-top:20px" />
                <div class="section-heading"><div><p class="eyebrow">MAKE TIME FOR YOU</p><h2>What’s your next move?</h2></div><p>Something familiar.<br />Or something entirely new.</p></div>
                <div class="categories"><button v-for="category in categories" :key="category.name" @click="choose(category.query)" :disabled="busy" :aria-pressed="serviceCategory === (category.query==='nail'?'nails':category.query)"><span class="category-image"><img :src="category.image" alt="" loading="lazy" /><span class="round-arrow"><ArrowUpRightIcon /></span></span><span class="category-text"><strong>{{ category.name }}</strong><span>{{ category.caption }}</span></span></button></div>
                <div id="salon-results" class="section-heading results-heading" tabindex="-1"><div><p class="eyebrow">FIND YOUR PEOPLE</p><h2>{{ filters.q || filters.location || filters.rating || filters.category || filters.date || filters.nearby ? 'Your search, your possibilities.' : 'Find a place you’ll love.' }}</h2></div><span class="result-count">{{ results.total }} {{ results.total === 1 ? 'business' : 'businesses' }}</span></div>
                <div class="mp-results-toolbar"><div class="mp-toolbar-choices"><button class="mp-filter-chip" :aria-pressed="appointmentDate==='today'" :disabled="busy" @click="appointmentDate=appointmentDate==='today'?'':'today';search()"><CalendarDaysIcon/>Available today</button><button class="mp-filter-chip" :aria-pressed="rating==='4.5'" :disabled="busy" @click="rating=rating==='4.5'?'':'4.5';search()">☆ Top rated</button><button v-if="filters.q || filters.location || filters.rating || filters.category || filters.date || filters.nearby" class="mp-button quiet" :disabled="busy" @click="resetSearch">Clear search</button></div><label class="mp-sort"><span class="ds-sr-only">Sort businesses</span><select v-model="sort" @change="search"><option value="recommended">Recommended</option><option value="name">Name: A–Z</option><option value="rating">Highest rated</option></select></label></div>
                <div aria-live="polite" :aria-busy="busy">
                    <div class="mp-pills" v-if="results.data.length" aria-label="Result view"><button class="mp-pill" :aria-pressed="resultView==='list'" @click="resultView='list'">List view</button><button class="mp-pill" :aria-pressed="resultView==='map'" @click="resultView='map'">Map view</button></div><MarketplaceMap v-if="results.data.length && resultView==='map'" :key="JSON.stringify(filters)" :salons="results.data" @show-list="resultView='list'" /><div v-if="results.data.length && resultView==='list'" class="salons"><a v-for="salon in results.data" :key="salon.url" :href="salon.url" class="salon-card"><div class="salon-image"><img v-if="salon.image" :src="salon.image" :alt="salon.name" loading="lazy" /><span v-else class="salon-initial">{{ salon.name.slice(0, 1) }}</span><span class="book-label">Explore & book <ArrowUpRightIcon /></span></div><h3>{{ salon.name }}</h3><p v-if="salon.service">{{ salon.service }} · From {{ new Intl.NumberFormat(salon.locale || 'en', {style:'currency', currency:salon.currency}).format(salon.price_minor / 100) }}</p><p v-if="salon.new_on_marketplace">New on Marketplace</p><p v-if="salon.client_eligibility === 'existing' || salon.new_client_rule === 'existing_only'">Returning customers only</p><p v-if="salon.reviews.count" class="salon-rating" :aria-label="`Rated ${Number(salon.reviews.average).toFixed(1)} out of 5 from ${salon.reviews.count} ${salon.reviews.count === 1 ? 'review' : 'reviews'}`"><span aria-hidden="true">★</span> {{ Number(salon.reviews.average).toFixed(1) }} <span class="salon-rating-count">({{ salon.reviews.count }})</span></p><p>{{ salon.address }}</p><p v-if="salon.next_time">Next on this date: {{new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit',timeZone:salon.next_time.time_zone,timeZoneName:'short'}).format(new Date(salon.next_time.starts_at_utc))}}</p><p v-if="salon.distance!==null">About {{ salon.distance }} km away</p></a></div>
                    <AppNotice v-if="bounded" title="Narrow your search for more choices" description="These results cover a limited selection. Choose a service and area to find the best fit." /><AppNotice v-if="!results.data.length && alternatives?.length" title="Explore outside your selected area" description="No matches were found within 25 km. These alternatives are farther away; distances are straight-line estimates."><template #actions><a v-for="business in alternatives" :key="business.url" class="quiet-button" :href="business.url">{{ business.name }} · About {{ business.distance }} km away</a></template></AppNotice><AppNotice v-if="!results.data.length && !alternatives?.length" :title="filters.q || filters.location || filters.rating || filters.category || filters.date || filters.nearby ? 'No businesses match this search yet' : 'Your next favourite is on its way'" :description="filters.q || filters.location || filters.rating || filters.category || filters.date || filters.nearby ? 'Try another area, choose a different day, or clear your search to explore all available businesses.' : 'No businesses are available to book here yet. Check back soon or contact your usual salon.'"><template #actions><button v-if="filters.q || filters.location || filters.rating || filters.category || filters.date || filters.nearby" class="quiet-button" @click="resetSearch()">Explore all businesses</button><a href="#area-updates" class="quiet-button">Get updates for my area</a><Link href="/marketplace/guides" class="quiet-button">Explore our guides</Link></template></AppNotice>
                    <nav v-if="results.prev_page_url || results.next_page_url" class="pagination" aria-label="Appointment results pages"><Link v-if="results.prev_page_url" :href="results.prev_page_url">Previous</Link><span>Page {{ results.current_page }}</span><Link v-if="results.next_page_url" :href="results.next_page_url">Next</Link></nav>
                </div>
            </section>
            <section class="manifesto"><span class="eyebrow">LESS PLANNING. MORE LIVING.</span><h2>Find it. Book it.<br /><em>Make it your moment.</em></h2><div class="steps"><p><span>01</span><strong>Find your fit</strong>Explore real business photos and reviews from completed visits.</p><p><span>02</span><strong>Make it yours</strong>Choose your services and a time on the business’s booking page.</p><p><span>03</span><strong>See you there</strong>Pay your business directly. Your bookings, together in your account.</p></div></section>
            <div class="discovery" style="padding-bottom:0;padding-top:35px"><LaunchUpdates :city="filters.location || ''" /></div>
            <section class="business-band"><div><p class="eyebrow">CLIPPERDESK BUSINESS</p><h2>Your craft. A bigger audience.</h2><p>Run your day and make room for your next regular.</p></div><a href="/">Meet your business workspace <ArrowUpRightIcon /></a></section>
        </main>

    </MarketplaceLayout>
</template>

